"""Self-contained operator console with training, datasets, testing and settings tabs."""

from fastapi.responses import HTMLResponse


PAGE = """<!doctype html>
<!-- Hugging Face 模型 -->
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Lazy Agent Router</title><style>
:root{--ink:#172033;--muted:#64748b;--line:#e2e8f0;--blue:#2563eb;--blue-soft:#eff6ff;--bg:#f5f7fb}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.shell{max-width:1120px;margin:42px auto;padding:0 24px}.hero{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:22px}.hero h1{margin:0;font-size:28px}.hero p{margin:7px 0 0;color:var(--muted)}.badge{padding:7px 11px;border-radius:99px;background:#dcfce7;color:#166534;font-size:13px}.tabs{display:flex;gap:5px;border-bottom:1px solid var(--line);margin-bottom:20px;overflow:auto}.tab{margin:0;padding:11px 18px;border:0;border-radius:9px 9px 0 0;background:transparent;color:var(--muted);white-space:nowrap}.tab.active{background:white;color:var(--blue);box-shadow:inset 0 -2px var(--blue)}.panel{display:none}.panel.active{display:block}.grid{display:grid;grid-template-columns:1.2fr .8fr;gap:20px}.card{min-width:0;background:white;border:1px solid var(--line);border-radius:14px;padding:22px;box-shadow:0 8px 25px #24365a0a}.card+.card{margin-top:16px}h2{margin:0 0 8px;font-size:18px}h3{margin:0 0 10px;font-size:15px}.lead,.hint{color:var(--muted);line-height:1.55}.hint{font-size:13px}label{display:block;margin:14px 0 6px;font-weight:650;font-size:13px}textarea,input,select{width:100%;border:1px solid #cbd5e1;border-radius:9px;padding:10px 12px;background:white;color:var(--ink);font:inherit}textarea{min-height:126px;resize:vertical}.row{display:grid;grid-template-columns:1fr 1fr;gap:14px}.actions{display:flex;gap:10px;align-items:center;margin-top:16px}button{border:0;border-radius:8px;padding:10px 16px;background:var(--blue);color:white;font:inherit;font-weight:650;cursor:pointer}button.secondary{background:#e2e8f0;color:#334155}button:disabled{background:#94a3b8;cursor:wait}.status{padding:13px;border-radius:9px;background:var(--blue-soft);color:#1e40af;line-height:1.5}.progress-head{display:flex;justify-content:space-between;gap:16px;margin:18px 0 7px;font-size:13px;font-weight:650}.progress-track{width:100%;height:12px;overflow:hidden;border-radius:999px;background:#e2e8f0}.progress-bar{height:100%;width:0;background:linear-gradient(90deg,#2563eb,#60a5fa);border-radius:inherit;transition:width .25s ease}.training-detail{min-height:150px;max-height:310px}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:14px}.metric{padding:12px;border:1px solid var(--line);border-radius:10px}.metric b{display:block;font-size:18px}.metric span{color:var(--muted);font-size:12px}.dataset-item{display:flex;justify-content:space-between;gap:16px;padding:13px 0;border-bottom:1px solid var(--line)}.dataset-item:last-child{border-bottom:0}.dataset-item b{display:block}.dataset-item small{color:var(--muted)}pre{margin:14px 0 0;background:#0f172a;color:#dbeafe;border-radius:9px;padding:15px;min-height:230px;white-space:pre-wrap;overflow:auto}.config-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.config-grid label{margin-top:0}.config-grid small{display:block;color:var(--muted);margin-top:5px}.toast{margin-top:12px;color:#166534}.error{color:#b91c1c}.code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace}@media(max-width:760px){.shell{margin:24px auto}.hero{align-items:start;flex-direction:column}.grid,.row,.config-grid{grid-template-columns:1fr}.summary{grid-template-columns:1fr}.tabs{padding-bottom:1px}}
</style></head><body><main class="shell"><header class="hero"><div><h1>Lazy Agent Router 控制台</h1><p>管理数据集、动态训练参数与意图路由测试。</p></div><span class="badge" id="health">服务运行中</span></header>
<nav class="tabs" aria-label="控制台页面"><button class="tab active" data-tab="training">模型训练</button><button class="tab" data-tab="datasets">数据集</button><button class="tab" data-tab="testing">测试</button><button class="tab" data-tab="settings">配置</button></nav>

<section class="panel active" id="panel-training"><article class="card"><h2>启动训练</h2><p class="lead">选择基础模型和已校验数据集，配置页中的动态参数会随请求提交。</p><label for="model-source">训练基础模型</label><select id="model-source"></select><input id="custom-model" placeholder="本地模型路径或 Hugging Face 模型 ID" hidden><label for="training-dataset">训练数据集</label><select id="training-dataset"><option value="">内置 datasets/raw/intents.jsonl</option></select><div class="summary"><div class="metric"><b id="sum-epochs">5</b><span>最大轮数</span></div><div class="metric"><b id="sum-batch">16</b><span>Batch size</span></div><div class="metric"><b id="sum-lr">0.00002</b><span>学习率</span></div></div><div class="actions"><button id="start">开始训练</button><button class="secondary" data-open="settings">调整参数</button></div></article><article class="card"><h2>训练状态</h2><div class="status" id="training">正在获取训练状态…</div><div class="progress-head"><span id="progress-stage">等待开始</span><span id="progress-percent">0%</span></div><div class="progress-track" role="progressbar" aria-label="训练进度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><div class="progress-bar" id="progress-bar"></div></div><p class="hint">进度来自模型的真实参数更新步数。训练完成后，模型会自动加入测试页列表。</p><pre class="training-detail" id="training-detail">等待训练…</pre></article></section>

<section class="panel" id="panel-datasets"><div class="grid"><article class="card"><h2>上传 JSONL 数据集</h2><p class="lead">每行格式：<span class="code">{"text":"查询采购流程","intent":"workflow.query"}</span></p><label for="dataset">选择文件（最大 20 MB）</label><input id="dataset" type="file" accept=".jsonl,application/jsonl"><div class="actions"><button id="upload">上传并校验</button></div><div id="upload-message" class="toast"></div></article><aside class="card"><h2>数据要求</h2><p class="hint">必须包含 text 和 intent 字符串；空文本、冲突标签会被拒绝；每个意图至少两条样本，以确保训练集和验证集都覆盖该类别。</p></aside></div><article class="card"><h2>已上传数据集</h2><div id="dataset-list"><p class="hint">暂无数据集。</p></div></article></section>

<section class="panel" id="panel-testing"><div class="grid"><article class="card"><h2>意图路由测试</h2><label for="route-model">已训练模型</label><select id="route-model"><option>正在加载模型…</option></select><label for="query">用户查询</label><textarea id="query">帮我查询采购审批流程</textarea><button id="route">执行路由</button></article><aside class="card"><h2>路由结果</h2><pre id="result">等待查询…</pre></aside></div></section>

<section class="panel" id="panel-settings"><article class="card"><h2>动态训练参数</h2><p class="lead">这些值保存在当前浏览器，并在点击“开始训练”时通过 API 提交。后端仍会执行范围校验。</p><div class="config-grid" id="config-fields"></div><div class="actions"><button id="save-config">保存配置</button><button class="secondary" id="reset-config">恢复推荐值</button></div><div id="config-message" class="toast"></div></article></section>
</main><script>
const $=id=>document.getElementById(id);let defaults={},configSchema={},lastCompleted="";
const fieldMeta={epochs:["最大训练轮数","早停可能提前结束"],batch_size:["Batch size","显存不足时调小"],learning_rate:["学习率","续训建议 1e-5 左右"],max_length:["最大 Token 长度","短意图通常 64–128"],validation_split:["验证集比例","每类分层抽取"],reward_strength:["正确奖励强度","范围 [0, 1)"],penalty_strength:["错误惩罚强度","高置信错误的放大系数"],early_stopping_patience:["早停耐心","连续无改善轮数"],early_stopping_min_delta:["早停最小变化","过滤 loss 数值抖动"],weight_decay:["权重衰减","抑制小数据过拟合"],warmup_ratio:["预热比例","总更新步数的比例"],max_grad_norm:["梯度裁剪","限制异常大梯度"],gradient_accumulation_steps:["梯度累积步数","小显存模拟大 batch"],seed:["随机种子","固定后便于版本比较"],device:["训练设备","auto / cpu / cuda"]};
function showTab(name){document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===name));document.querySelectorAll('.panel').forEach(x=>x.classList.toggle('active',x.id===`panel-${name}`))}document.querySelectorAll('.tab').forEach(x=>x.onclick=()=>showTab(x.dataset.tab));document.querySelectorAll('[data-open]').forEach(x=>x.onclick=()=>showTab(x.dataset.open));
function addOption(select,value,label){const o=document.createElement('option');o.value=value;o.textContent=label;select.appendChild(o)}
function currentConfig(){const stored=JSON.parse(localStorage.getItem('lar-training-config')||'{}');return {...defaults,...stored}}
function renderSummary(){const c=currentConfig();$('sum-epochs').textContent=c.epochs;$('sum-batch').textContent=c.batch_size;$('sum-lr').textContent=c.learning_rate}
async function bootstrapConfig(){const r=await fetch('/v1/training/config'),d=await r.json();defaults=d.defaults;configSchema=d.schema.properties;const select=$('model-source');select.innerHTML='';d.recommended_models.forEach(m=>addOption(select,m.id,m.label));addOption(select,'custom','自定义模型 ID / 本地路径');renderConfig();renderSummary()}
function renderConfig(){const root=$('config-fields'),values=currentConfig();root.innerHTML='';Object.entries(fieldMeta).forEach(([name,meta])=>{const box=document.createElement('div'),label=document.createElement('label'),input=name==='device'?document.createElement('select'):document.createElement('input'),small=document.createElement('small'),schema=configSchema[name]||{};label.textContent=meta[0];label.htmlFor=`cfg-${name}`;input.id=`cfg-${name}`;input.dataset.config=name;if(name==='device'){['auto','cuda','cpu'].forEach(v=>addOption(input,v,v))}else{input.type='number';input.step=['epochs','batch_size','max_length','early_stopping_patience','gradient_accumulation_steps','seed'].includes(name)?'1':'any';if(schema.minimum!==undefined)input.min=schema.minimum;if(schema.maximum!==undefined)input.max=schema.maximum}input.value=values[name];small.textContent=meta[1];box.append(label,input,small);root.appendChild(box)})}
$('save-config').onclick=()=>{const next={};document.querySelectorAll('[data-config]').forEach(input=>{const name=input.dataset.config;next[name]=name==='device'?input.value:Number(input.value)});localStorage.setItem('lar-training-config',JSON.stringify(next));$('config-message').textContent='配置已保存，下一次训练将使用这些参数。';renderSummary()};$('reset-config').onclick=()=>{localStorage.removeItem('lar-training-config');renderConfig();renderSummary();$('config-message').textContent='已恢复推荐值。'};
async function datasets(){const r=await fetch('/v1/datasets'),d=await r.json(),select=$('training-dataset'),list=$('dataset-list'),selected=select.value;select.innerHTML='';addOption(select,'','内置 datasets/raw/intents.jsonl');d.datasets.forEach(x=>addOption(select,x.id,`${x.name}（${x.rows} 条 / ${x.intents} 类）`));select.value=selected;list.innerHTML='';if(!d.datasets.length){list.innerHTML='<p class="hint">暂无数据集。</p>';return}d.datasets.forEach(x=>{const row=document.createElement('div');row.className='dataset-item';const left=document.createElement('div'),name=document.createElement('b'),info=document.createElement('small'),date=document.createElement('small');name.textContent=x.name;info.textContent=`${x.rows} 条 · ${x.intents} 个意图 · ${(x.size_bytes/1024).toFixed(1)} KB`;date.textContent=new Date(x.created_at).toLocaleString();left.append(name,info);row.append(left,date);list.appendChild(row)})}
$('upload').onclick=async()=>{const file=$('dataset').files[0],msg=$('upload-message'),button=$('upload');if(!file){msg.className='toast error';msg.textContent='请先选择 JSONL 文件。';return}button.disabled=true;msg.className='toast';msg.textContent='正在上传并校验…';const form=new FormData();form.append('dataset',file);try{const r=await fetch('/v1/datasets',{method:'POST',body:form}),d=await r.json();if(!r.ok)throw new Error(d.detail||'上传失败');msg.textContent=`上传成功：${d.rows} 条记录，${d.intents} 个意图。`;await datasets()}catch(e){msg.className='toast error';msg.textContent=e.message}finally{button.disabled=false}};
async function models(){const r=await fetch('/v1/models'),d=await r.json(),select=$('route-model'),selected=select.value;select.innerHTML='';d.models.forEach(m=>addOption(select,m.id,m.label));if([...select.options].some(x=>x.value===selected))select.value=selected}
async function status(){const r=await fetch('/v1/training/status'),d=await r.json(),button=$('start'),progress=d.progress||{},percent=Math.max(0,Math.min(100,Number(progress.percent)||0)),track=document.querySelector('.progress-track');$('training').textContent=d.message;button.disabled=d.state==='running';button.textContent=d.state==='running'?'训练中…':'开始训练';$('progress-bar').style.width=`${percent}%`;$('progress-percent').textContent=`${percent}%`;$('progress-stage').textContent=d.state==='running'?`Epoch ${progress.epoch||0} · Step ${progress.step||0}/${progress.total_steps||0}`:d.state==='completed'?'训练完成':d.state==='failed'?'训练失败':'等待开始';track.setAttribute('aria-valuenow',String(percent));$('training-detail').textContent=JSON.stringify(d,null,2);if(d.state==='completed'&&d.output_dir!==lastCompleted){lastCompleted=d.output_dir;models()}}
$('model-source').onchange=()=>$('custom-model').hidden=$('model-source').value!=='custom';$('start').onclick=async()=>{const button=$('start'),form=new FormData(),source=$('model-source').value==='custom'?$('custom-model').value.trim():$('model-source').value;if(!source){$('training').textContent='请填写自定义模型路径或 Hugging Face ID。';return}button.disabled=true;form.append('model_source',source);form.append('parameters',JSON.stringify(currentConfig()));if($('training-dataset').value)form.append('dataset_id',$('training-dataset').value);try{const r=await fetch('/v1/training/start',{method:'POST',body:form}),d=await r.json();if(!r.ok)throw new Error(typeof d.detail==='string'?d.detail:JSON.stringify(d.detail));$('training').textContent=d.message;$('training-detail').textContent=JSON.stringify(d,null,2)}catch(e){$('training').textContent='启动失败：'+e.message}finally{status()}};
$('route').onclick=async()=>{const b=$('route'),out=$('result');b.disabled=true;out.textContent='正在路由…';try{const r=await fetch('/v1/route',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({query:$('query').value,model:$('route-model').value})}),d=await r.json();if(!r.ok)throw new Error(d.detail||'请求失败');out.textContent=JSON.stringify(d,null,2)}catch(e){out.textContent='请求失败：'+e.message}finally{b.disabled=false}};
Promise.all([bootstrapConfig(),datasets(),models()]).then(status);setInterval(status,3000);
</script></body></html>"""


def console_page() -> HTMLResponse:
    return HTMLResponse(PAGE)
